const PRE_UPSTREAM_NAMES = CANONICAL_LEDGERS.filter(({ name }) => name !== UPSTREAM_LEDGER)
  .filter(({ name }) => name !== OPERATOR_ACTIONS_LEDGER)
  .map(({ name }) => name)
