function publicSnapshot(store: LedgerStore, names: readonly string[]): PublicSnapshot {
  return Object.fromEntries(names.map((name) => [name, structuredClone(store.fetch(name))]));
}

function withoutPlanLifecycleSchemaFields(snapshot: PublicSnapshot): PublicSnapshot {
  const compatible = structuredClone(snapshot);
  for (const ledger of Object.values(compatible)) {
    for (const field of WORKSET_OWNED_FIELD_NAMES) delete ledger.schema.fields[field];
  }
  const goals = compatible[GOALS_LEDGER];
  if (goals !== undefined) {
    for (const field of PLAN_MANAGED_GOAL_FIELD_NAMES) delete goals.schema.fields[field];
  }
  const reviews = compatible[REVIEWS_LEDGER];
  if (reviews !== undefined) delete reviews.schema.fields[PLAN_REVIEW_DRAFT_FIELD];
  const ideas = compatible[IDEAS_LEDGER];
  if (ideas !== undefined) delete ideas.schema.fields.ledgerRefs;
  return compatible;
}

function withoutPlanLifecycleFields(
  ledgerName: string,
  schema: LedgerSchema,
): LedgerSchema {
  const compatible = structuredClone(schema);
  for (const field of WORKSET_OWNED_FIELD_NAMES) delete compatible.fields[field];
  if (ledgerName === GOALS_LEDGER) {
    for (const field of PLAN_MANAGED_GOAL_FIELD_NAMES) delete compatible.fields[field];
  }
  if (ledgerName === REVIEWS_LEDGER) delete compatible.fields[PLAN_REVIEW_DRAFT_FIELD];
  if (ledgerName === IDEAS_LEDGER) delete compatible.fields.ledgerRefs;
  return compatible;
}

function withoutPlanLifecycleSchemaRows(
  rows: Array<Record<string, unknown>>,
): Array<Record<string, unknown>> {
  return rows.map((row) => {
    const name = row["name"];
    const storedSchema = row["schema_json"];
    if (
      typeof name !== "string" ||
      (typeof storedSchema !== "string" &&
        (storedSchema === null || typeof storedSchema !== "object"))
    ) {
      throw new Error("invalid captured ledger schema row");
    }
    const schema =
      typeof storedSchema === "string"
        ? (JSON.parse(storedSchema) as LedgerSchema)
        : (storedSchema as LedgerSchema);
    const compatible = withoutPlanLifecycleFields(name, schema);
    return {
      ...row,
      schema_json:
        typeof storedSchema === "string" ? JSON.stringify(compatible) : compatible,
    };
  });
}

async function assertAdditivePublicState(
  store: LedgerStore,
  expected: FrozenPublicFixture,
): Promise<void> {
  expect(store.enumerate().sort()).toEqual(CURRENT_NAMES);
  expect(withoutPlanLifecycleSchemaFields(publicSnapshot(store, PRE_UPSTREAM_NAMES))).toEqual(
    expected.ledgers,
  );

  for (const [key, archive] of Object.entries(expected.archives)) {
    const separator = key.indexOf("/");
    if (separator < 1) throw new Error(`invalid frozen archive key: ${key}`);
    const ledger = key.slice(0, separator);
    const pointer = key.slice(separator + 1);
    expect(await store.fetchArchive(ledger, pointer)).toEqual(archive);
  }

  for (const { name, schema } of POST_FIXTURE_CANONICAL_LEDGERS) {
    const additive = store.fetch(name);
    expect(additive.schema).toEqual(schema);
    expect(additive.counters).toEqual({ milestone: 0, item: 0 });
    expect(additive.milestones).toEqual([]);
    expect(additive.archivePointers).toEqual([]);
  }
}

async function assertLegacyLogs(store: LedgerStore): Promise<void> {
  if (!("readLog" in store)) {
    throw new Error("persistent fixture store does not expose readLog");
  }
  const readable = store as LedgerStore & LogReadableStore;
  const session = await readable.readLog(SESSION_LOG_REF);
  const raw = await readable.readLog(RAW_LOG_REF);
  expect(session).toEqual({
    path: SESSION_LOG_REF,
    content: "# Legacy session\n\nProduced before the upstream ledger existed.\n",
  });
  expect(raw).toEqual({
    path: RAW_LOG_REF,
    content: '{"type":"assistant","message":{"content":"legacy raw transcript"}}\n',
  });
}

interface PersistentFixture {
  readonly expected: FrozenPublicFixture;
  open(): LedgerStore;
  capturePriorRawState(): Promise<string>;
  captureCompleteRawState(): Promise<string>;
  assertNoDivergenceBackup(): Promise<void>;
}

async function runPersistentContract(fixture: PersistentFixture): Promise<void> {
  const rawBefore = await fixture.capturePriorRawState();

  const first = fixture.open();
  await first.init();
  try {
    await assertAdditivePublicState(first, fixture.expected);
    await assertLegacyLogs(first);
  } finally {
    await first.dispose();
  }

  expect(await fixture.capturePriorRawState()).toBe(rawBefore);
  await fixture.assertNoDivergenceBackup();
  const completeAfterFirst = await fixture.captureCompleteRawState();

  const second = fixture.open();
  await second.init();
  try {
    await assertAdditivePublicState(second, fixture.expected);
    await assertLegacyLogs(second);
  } finally {
    await second.dispose();
  }

  expect(await fixture.captureCompleteRawState()).toBe(completeAfterFirst);
  await fixture.assertNoDivergenceBackup();
}

async function freshRoot(prefix: string): Promise<string> {
  const root = await mkdtemp(path.join(tmpdir(), prefix));
  roots.push(root);
  return root;
}

async function relativeFiles(root: string, prefix: string): Promise<string[]> {
  const directory = path.join(root, prefix);
  const entries = await readdir(directory, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    const relative = path.join(prefix, entry.name);
    if (entry.isDirectory()) files.push(...(await relativeFiles(root, relative)));
    else if (entry.isFile()) files.push(relative);
  }
  return files.sort();
}

async function captureFiles(root: string, paths: readonly string[]): Promise<string> {
  const contents = await Promise.all(
    paths.map(async (file) => [file, (await readFile(path.join(root, file))).toString("base64")]),
  );
  return JSON.stringify(contents);
}

async function captureLogFiles(logsDir: string): Promise<string> {
  return captureFiles(logsDir, LOG_PATHS);
}

async function frozenFsPaths(): Promise<string[]> {
  return relativeFiles(path.join(FS_FIXTURE_ROOT, LEDGER_STORAGE_DIRNAME), "");
}

async function captureFsPriorState(storageDir: string): Promise<string> {
  const paths = (await frozenFsPaths()).filter((file) => file !== "ledgers.yaml");
  const registry = parseRegistry(await readFile(path.join(storageDir, "ledgers.yaml"), "utf8"));
  return JSON.stringify({
    registry: registry.ledgers
      .filter(({ name }) => !POST_FIXTURE_LEDGER_NAMES.has(name))
      .map((entry) => ({
        ...entry,
        schema: withoutPlanLifecycleFields(entry.name, entry.schema),
      })),
    files: JSON.parse(await captureFiles(storageDir, paths)) as unknown,
  });
}

async function captureCompleteFsState(storageDir: string): Promise<string> {
  const paths = (await relativeFiles(storageDir, "")).filter(
    (file) => !file.startsWith(".backup/") && !file.startsWith(".locks/"),
  );
  return captureFiles(storageDir, paths);
}

