const SQLITE_TABLES = ["groups", "items", "archive_pointers", "archived_items", "meta"] as const;

async function captureSqliteState(
  dbPath: string,
  logsDir: string,
  includeUpstream: boolean,
): Promise<string> {
  const db = openLedgerDb(dbPath);
  try {
    const ledgerRows = includeUpstream
      ? db
          .query(
            "SELECT name, schema_json, milestone_counter, item_counter FROM ledgers ORDER BY rowid",
          )
          .all()
      : db
          .query(
            "SELECT name, schema_json, milestone_counter, item_counter FROM ledgers WHERE name NOT IN (?, ?) ORDER BY rowid",
          )
          .all(UPSTREAM_LEDGER, OPERATOR_ACTIONS_LEDGER);
    const ledgers = includeUpstream
      ? ledgerRows
      : withoutPlanLifecycleSchemaRows(
          ledgerRows as Array<Record<string, unknown>>,
        );
    const tables = Object.fromEntries(
      SQLITE_TABLES.map((table) => [
        table,
        db.query(`SELECT * FROM ${table} ORDER BY rowid`).all(),
      ]),
    );
    // T1509 (G155): the sanctioned v2→v3 in-place bump makes the
    // schema_version marker a moving target across store generations. The
    // byte-identity contract covers DATA, not the migration marker, so the
    // marker row is normalized to a constant before comparison.
    tables["meta"] = (tables["meta"] as Array<Record<string, unknown>>).map((row) =>
      row["key"] === "schema_version" ? { ...row, value: "MIGRATED" } : row,
    );
    return JSON.stringify({ ledgers, tables, logs: JSON.parse(await captureLogFiles(logsDir)) });
  } finally {
    db.close();
  }
}

