async function capturePostgresState(
  pool: SQL,
  projectKey: string,
  includeUpstream: boolean,
): Promise<string> {
  const projects = await pool<Array<Record<string, unknown>>>`
    SELECT project_key, display_name, created_at::text, updated_at::text
    FROM projects WHERE project_key = ${projectKey}
  `;
  const ledgerRows = includeUpstream
    ? await pool<Array<Record<string, unknown>>>`
        SELECT name, schema_json, milestone_counter, item_counter
        FROM ledgers WHERE project_key = ${projectKey} ORDER BY name
      `
    : await pool<Array<Record<string, unknown>>>`
        SELECT name, schema_json, milestone_counter, item_counter
        FROM ledgers
        WHERE project_key = ${projectKey}
          AND name <> ${UPSTREAM_LEDGER}
          AND name <> ${OPERATOR_ACTIONS_LEDGER}
        ORDER BY name
      `;
  const ledgers = includeUpstream
    ? ledgerRows
    : withoutPlanLifecycleSchemaRows(ledgerRows);
  const groups = await pool<Array<Record<string, unknown>>>`
    SELECT seq::text, ledger, id, title, description
    FROM groups WHERE project_key = ${projectKey} ORDER BY seq
  `;
  const items = await pool<Array<Record<string, unknown>>>`
    SELECT seq::text, ledger, id, milestone_id, status, fields_json,
           created_at, updated_at, author, session
    FROM items WHERE project_key = ${projectKey} ORDER BY seq
  `;
  const pointers = await pool<Array<Record<string, unknown>>>`
    SELECT seq::text, ledger, id, summary, title, status, archived_at
    FROM archive_pointers WHERE project_key = ${projectKey} ORDER BY seq
  `;
  const archived = await pool<Array<Record<string, unknown>>>`
    SELECT seq::text, ledger, pointer_id, id, milestone_id, status, fields_json,
           created_at, updated_at, author, session
    FROM archived_items WHERE project_key = ${projectKey} ORDER BY seq
  `;
  const logs = await pool<Array<Record<string, unknown>>>`
    SELECT path, content, created_at::text
    FROM logs WHERE project_key = ${projectKey} ORDER BY path
  `;
  return JSON.stringify({ projects, ledgers, groups, items, pointers, archived, logs });
}

async function cleanupPostgresTenantFamily(pool: SQL, projectKey: string): Promise<void> {
  const tenants = await pool<Array<{ project_key: string }>>`
    SELECT project_key FROM projects
    WHERE project_key = ${projectKey}
       OR project_key LIKE ${`${projectKey}__divergence-backup-%`}
    ORDER BY project_key
  `;
  for (const { project_key: tenant } of tenants) {
    await pool.begin(async (tx) => {
      await tx`DELETE FROM archived_items WHERE project_key = ${tenant}`;
      await tx`DELETE FROM archive_pointers WHERE project_key = ${tenant}`;
      await tx`DELETE FROM items WHERE project_key = ${tenant}`;
      await tx`DELETE FROM groups WHERE project_key = ${tenant}`;
      await tx`DELETE FROM ledgers WHERE project_key = ${tenant}`;
      await tx`DELETE FROM logs WHERE project_key = ${tenant}`;
      await tx`DELETE FROM projects WHERE project_key = ${tenant}`;
    });
  }
}

async function preparePostgresFixture(
  setupPool: SQL,
  postgresUrl: string,
  projectKey: string,
): Promise<PersistentFixture> {
  const expected = await expectedPublicFixture;
  await ensurePostgresSchema(setupPool);
  const sql = (await readFile(POSTGRES_FIXTURE, "utf8")).replaceAll("__PROJECT_KEY__", projectKey);
  for (const statement of sql.split(/;\s*\n/)) {
    const query = statement.trim();
    if (query.length > 0) await setupPool.unsafe(query);
  }

  const names = await setupPool<Array<{ name: string }>>`
    SELECT name FROM ledgers WHERE project_key = ${projectKey} ORDER BY name
  `;
  expect(names.map(({ name }) => name)).toEqual(PRE_UPSTREAM_NAMES);

  return {
    expected,
    open: () =>
      new PostgresLedgerStore({
        pool: openPgPool(postgresUrl),
        projectKey,
        displayName: "Legacy pre-upstream fixture",
        now,
      }),
    capturePriorRawState: () => capturePostgresState(setupPool, projectKey, false),
    captureCompleteRawState: () => capturePostgresState(setupPool, projectKey, true),
    async assertNoDivergenceBackup() {
      const shadows = await setupPool<Array<{ project_key: string }>>`
        SELECT project_key FROM projects
        WHERE project_key LIKE ${`${projectKey}__divergence-backup-%`}
      `;
      expect(shadows).toEqual([]);
    },
  };
}

function normalizeDump(dump: readonly BackupDumpFile[]): BackupDumpFile[] {
  return [...dump].sort((left, right) => left.path.localeCompare(right.path));
}

describe("pre-upstream immutable fixture provenance", () => {
  test("fixtures came from T794's first parent and contain archived data plus logs", async () => {
    const manifest = JSON.parse(
      await readFile(path.join(FIXTURE_DIR, "manifest.json"), "utf8"),
    ) as {
      sourceRevision: string;
    };
    const expected = await expectedPublicFixture;
    const memory = await memoryFixture;

    expect(manifest.sourceRevision).toBe(FIXTURE_REVISION);
    expect(expected.sourceRevision).toBe(FIXTURE_REVISION);
    expect(memory.sourceRevision).toBe(FIXTURE_REVISION);
    expect(Object.keys(expected.ledgers).sort()).toEqual(PRE_UPSTREAM_NAMES);
    expect(expected.archives["tasks/M42"]).toEqual({
      kind: "group",
      milestone: expect.objectContaining({
        id: "M42",
        items: [expect.objectContaining({ id: "T52" })],
      }),
    });
    expect(memory.logs.map(({ path: logPath }) => logPath).sort()).toEqual(
      [RAW_LOG_REF, SESSION_LOG_REF].sort(),
    );
    expect(await captureLogFiles(path.join(FS_FIXTURE_ROOT, ".cq", "logs"))).toBe(
      await expectedLogState,
    );
  });

  test("git divergence-tag oracle detects and can isolate a matching sentinel", async () => {
    const root = await initGitRepository();
    const sentinel = "cq-ledger-backup-sentinel";
    const sentinelRef = `refs/tags/${sentinel}`;
    await exec("git", ["tag", sentinel], { cwd: root });
    try {
      expect(await divergenceBackupTags(root)).toEqual([sentinelRef]);
    } finally {
      await exec("git", ["tag", "--delete", sentinel], { cwd: root });
    }
    expect(await divergenceBackupTags(root)).toEqual([]);
  });
});

describe("pre-upstream canonical-ledger initialization", () => {
  test("FsLedgerStore adds only an empty upstream ledger and a second init is idempotent", async () => {
    await runPersistentContract(await prepareFsFixture());
  });

  test("GitObjectLedgerBackend adds only an empty upstream ledger without a divergence tag", async () => {
    await runPersistentContract(await prepareGitFixture());
  }, 30_000);

  test("SqliteLedgerStore adds only an empty upstream row transactionally", async () => {
    await runPersistentContract(await prepareSqliteFixture());
  });

  test("InMemoryLedgerStore hydrates the frozen serialized seed additively", async () => {
    const expected = await expectedPublicFixture;
    const frozen = await memoryFixture;
    const store = new InMemoryLedgerStore({ now });
    const fixtureState = store as unknown as {
      ledgers: Map<string, Ledger>;
      archives: Map<string, unknown>;
      itemArchives: Map<string, unknown>;
      initialised: boolean;
    };
    fixtureState.ledgers = new Map(structuredClone(frozen.ledgers));
    fixtureState.archives = new Map(structuredClone(frozen.archives));
    fixtureState.itemArchives = new Map(structuredClone(frozen.itemArchives));
    fixtureState.initialised = false;
    const priorBytes = JSON.stringify({
      ledgers: frozen.ledgers,
      archives: frozen.archives,
      itemArchives: frozen.itemArchives,
      logs: frozen.logs,
    });

    await store.init();
    await assertAdditivePublicState(store, expected);
    expect(
      JSON.stringify({
        ledgers: Array.from(fixtureState.ledgers.entries()).filter(
          ([name]) => !POST_FIXTURE_LEDGER_NAMES.has(name),
        ),
        archives: Array.from(fixtureState.archives.entries()),
        itemArchives: Array.from(fixtureState.itemArchives.entries()),
        logs: frozen.logs,
      }),
    ).toBe(priorBytes);
    const afterFirst = JSON.stringify(Array.from(fixtureState.ledgers.entries()));

    await store.init();
    await assertAdditivePublicState(store, expected);
    expect(JSON.stringify(Array.from(fixtureState.ledgers.entries()))).toBe(afterFirst);
    await store.dispose();
  });
});

describe.skipIf(!PG_URL)("pre-upstream PostgreSQL tenant initialization", () => {
  const setupPool = PG_URL === undefined ? undefined : openPgPool(PG_URL);
  const tenantKeys = new Set<string>();

  afterAll(async () => {
    if (setupPool === undefined) return;
    for (const projectKey of tenantKeys) {
      await cleanupPostgresTenantFamily(setupPool, projectKey);
    }
    tenantKeys.clear();
    await setupPool.close();
  });

  test("PostgresLedgerStore adds only an empty tenant-scoped upstream row", async () => {
    if (setupPool === undefined || PG_URL === undefined) {
      throw new Error("PostgreSQL fixture test ran without CQ_TEST_PG_URL");
    }
    const projectKey = `t796-${randomUUID()}`;
    tenantKeys.add(projectKey);
    try {
      const fixture = await preparePostgresFixture(setupPool, PG_URL, projectKey);
      await runPersistentContract(fixture);
    } finally {
      await cleanupPostgresTenantFamily(setupPool, projectKey);
      tenantKeys.delete(projectKey);
    }
  }, 30_000);
});

describe("pre-upstream lifecycle acceptance states", () => {
  test("portable backup and XDG restore preserve every upgraded datum and log byte", async () => {
    const fixture = await prepareFsFixture();
    const source = fixture.open();
    await source.init();
    await assertAdditivePublicState(source, fixture.expected);
    const expected = publicSnapshot(source, CURRENT_NAMES);
    const sourceLogs = path.join(fixture.root, ".cq", "logs");
    const dump = await buildBackupDump(source, sourceLogs);
    await source.dispose();

    const registryFile = dump.find(({ path: file }) => file === "ledgers.yaml");
    if (registryFile === undefined) {
      throw new Error("Portable backup omitted ledgers.yaml");
    }
    const dumpedRegistry = parseRegistry(registryFile.content);
    expect(dumpedRegistry.ledgers).toContainEqual(
      expect.objectContaining({ name: UPSTREAM_LEDGER, schema: UPSTREAM_SCHEMA }),
    );
    expect(dump.map(({ path: file }) => file)).toEqual(
      expect.arrayContaining([
        `${UPSTREAM_LEDGER}.md`,
        "archive/tasks/M42.md",
        "archive/milestones/M42.md",
        "logs/20260724-legacy-session.md",
        "logs/raw/20260724-legacy-worker.jsonl",
      ]),
    );

    const destinationRoot = await freshRoot("t796-restore-");
    const dbPath = path.join(destinationRoot, "ledger.db");
    const logsDir = path.join(destinationRoot, "logs");
    await restoreDumpToXdg({
      dbPath,
      logsDir,
      dump,
      authority: mintWorksetManagementAuthority(),
      overwriteAuthorized: false,
    });
    const restored = new SqliteLedgerStore({ dbPath, logsDir, now });
    await restored.init();
    try {
      expect(publicSnapshot(restored, CURRENT_NAMES)).toEqual(expected);
      await assertAdditivePublicState(restored, fixture.expected);
      await assertLegacyLogs(restored);
      expect(normalizeDump(await buildBackupDump(restored, logsDir))).toEqual(normalizeDump(dump));
      const next = await restored.createItem(UPSTREAM_LEDGER, "M41", {
        status: "open",
        fields: {
          headline: "post-restore upstream report",
          package: "@cq/example",
        },
      });
      expect(next.id).toBe("U1");
    } finally {
      await restored.dispose();
    }
  });

  test("reset preserves legacy archive/log bytes, retains upstream canon, and erase removes it", async () => {
    const fixture = await prepareFsFixture();
    const store = fixture.open();
    await store.init();
    await store.createItem(UPSTREAM_LEDGER, "M41", {
      status: "open",
      fields: {
        headline: "reset target",
        package: "@cq/example",
      },
    });

    if (!(store instanceof FsLedgerStore)) {
      throw new Error("expected FsLedgerStore fixture");
    }
    const summary = await store.reset();
    expect(summary.ledgers).toContainEqual(
      expect.objectContaining({ name: UPSTREAM_LEDGER, itemCount: 1 }),
    );
    expect(store.enumerate()).toEqual(CURRENT_NAMES);
    expect(store.fetch(UPSTREAM_LEDGER).counters).toEqual({ milestone: 0, item: 0 });
    expect(store.fetch(UPSTREAM_LEDGER).milestones).toEqual([]);
    await store.dispose();

    const storageDir = path.join(fixture.root, LEDGER_STORAGE_DIRNAME);
    expect(await readFile(path.join(summary.backupDir, `${UPSTREAM_LEDGER}.md`), "utf8")).toContain(
      "# upstream",
    );
    const legacyArtifacts = [
      "archive/tasks/M42.md",
      "archive/milestones/M42.md",
      "logs/20260724-legacy-session.md",
      "logs/raw/20260724-legacy-worker.jsonl",
    ];
    expect(await captureFiles(storageDir, legacyArtifacts)).toBe(
      await captureFiles(path.join(FS_FIXTURE_ROOT, ".cq"), legacyArtifacts),
    );
    const erased = await removeLedgerArtifacts(storageDir);
    expect(erased.removed.some((entry) => entry.endsWith(`${UPSTREAM_LEDGER}.md`))).toBe(true);
    await expect(stat(storageDir)).rejects.toMatchObject({ code: "ENOENT" });
    expect((await readdir(fixture.root)).sort()).toEqual([]);
  });
});
